-     * @return the voter set if one exist, otherwise {@code Optional.empty()}
-     */
-    public Optional<VoterSet> valueAtOrBefore(long offset) {
-        return votersHistory.valueAtOrBefore(offset);
-    }
-
-    /**
-     * Returns the latest set of voters.
